    rooms: ["o_sonar", "o_ballast", "o_okopanel", "o_quietnook", "o_repeatroom", "pumps", "tankfarm", "comms", "compressor", "barochamber", "vacuum", "storage", "repair", "bunker", "cafeteria"],
